    const clone = value => JSON.parse(JSON.stringify(value));
    const nowText = () => new Date().toLocaleString('zh-CN', { hour12: false });
    const esc = value => String(value ?? '')
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#39;');

    function context() {
        return globalThis.SillyTavern?.getContext?.() ?? null;
    }

    function getEvents(ctx) {
        return ctx?.event_types ?? ctx?.eventTypes ?? globalThis.event_types ?? {};
    }

    function nativeChatId(ctx) {
        if (!ctx) return '';
        const values = [
            ctx.chatId,
            ctx.chat_id,
            ctx.getCurrentChatId?.(),
            ctx.chatMetadata?.chat_id,
            ctx.chatMetadata?.chatId,
            ctx.chatMetadata?.file_name,
            ctx.chatMetadata?.fileName,
        ];
        const value = values.find(item => item !== undefined && item !== null && String(item).trim());
        return value ? String(value).trim() : '';
    }

    function getChatKey(ctx = context()) {
        if (!ctx) return 'no-chat';
        const native = nativeChatId(ctx);
        if (native) return `native:${native}`;

        // 旧版用 characterId + chat.length 当 key。两个新聊天只要同角色、同楼层数就会撞 key，
        // 从而把旧聊天的 localStorage / 检索索引带进新聊天。v0.8.0 改为真正的聊天实例 ID。
        if (ctx.chatMetadata && typeof ctx.chatMetadata === 'object') {
            let id = String(ctx.chatMetadata[CHAT_INSTANCE_META_KEY] || '').trim();
            if (!id) {
                id = `meta-${globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`}`;
                ctx.chatMetadata[CHAT_INSTANCE_META_KEY] = id;
            }
            return `meta:${id}`;
        }

        const chat = ctx.chat;
        if (chat && typeof chat === 'object') {
            if (!chatRuntimeIds.has(chat)) chatRuntimeIds.set(chat, `runtime-${globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`}`);
            return chatRuntimeIds.get(chat);
        }
        return `runtime:${globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`}`;
    }

    function currentChatAnchor(ctx = context()) {
        const chat = ctx?.chat || [];
        const firstUserIndex = chat.findIndex(message => message?.is_user && String(message?.mes ?? message?.message ?? message?.text ?? '').trim());
        if (firstUserIndex < 0) return '';
        const firstUser = String(chat[firstUserIndex]?.mes ?? chat[firstUserIndex]?.message ?? chat[firstUserIndex]?.text ?? '').trim().slice(0, 1200);
        const firstAssistant = String(chat.find(message => !message?.is_user && !message?.is_system)?.mes ?? '').trim().slice(0, 700);
        const raw = `${ctx?.characterId ?? ctx?.character_id ?? ''}|${firstUser}|${firstAssistant}`;
        let hash = 2166136261;
        for (const char of raw) { hash ^= char.charCodeAt(0); hash = Math.imul(hash, 16777619); }
        return `anchor-${(hash >>> 0).toString(16)}-${raw.length}`;
    }

    function currentCharacterArchiveIdentity(ctx = context()) {
        const characterId = String(ctx?.characterId ?? ctx?.character_id ?? ctx?.chatMetadata?.character_id ?? '').trim();
        const characterName = String(ctx?.name2 ?? ctx?.characterName ?? ctx?.chatMetadata?.character_name ?? '未命名角色').trim() || '未命名角色';
        const avatar = String(ctx?.characters?.[ctx?.characterId]?.avatar ?? ctx?.chatMetadata?.avatar ?? '').trim();
        const characterKey = characterId ? `character-id:${characterId}` : `character-name:${characterName}|avatar:${avatar}`;
        const chatKey = getChatKey(ctx);
        const chatName = nativeChatId(ctx) || String(ctx?.chatMetadata?.chat_name ?? ctx?.chatMetadata?.file_name ?? '当前聊天');
        return { characterKey, characterId, characterName, avatar, chatKey, chatName, chatAnchor: currentChatAnchor(ctx) };
    }

    function captureChatScope(ctx = context()) {
        if (!ctx) return null;
        const chatKey = getChatKey(ctx);
        const remembered = ctx?.chatMetadata?.[ARCHIVE_BINDING_META_KEY] || {};
        const runtimeBinding = stateRuntime.archiveBindingChatKey === chatKey ? stateRuntime.archiveBinding : null;
        const chat = Array.isArray(ctx.chat) ? ctx.chat : [];
        return {
            epoch: Number(stateRuntime.chatEpoch || 0),
            chatKey,
            chatAnchor: currentChatAnchor(ctx),
            serverChatKey: serverChatKey(ctx),
            identity: currentCharacterArchiveIdentity(ctx),
            hasMessages: chat.some(message => String(messageText(message) || '').trim()),
            rememberedArchiveId: String(remembered?.archiveId || runtimeBinding?.archiveId || ''),
            binding: runtimeBinding ? clone(runtimeBinding) : null,
            localStorageKey: `${MODULE}:${chatKey}`,
        };
    }

    function chatScopeIsCurrent(scope) {
        return Boolean(scope)
            && Number(scope.epoch) === Number(stateRuntime.chatEpoch)
            && String(scope.chatKey || '') === String(getChatKey());
    }

    function rememberArchiveBindingForCurrentChat(scope, binding) {
        if (!binding || !chatScopeIsCurrent(scope)) return;
        stateRuntime.archiveBinding = binding;
        stateRuntime.archiveBindingChatKey = scope.chatKey;
        const ctx = context();
        if (!ctx?.chatMetadata || getChatKey(ctx) !== scope.chatKey) return;
        ctx.chatMetadata[ARCHIVE_BINDING_META_KEY] = {
            archiveId:binding.archiveId,
            characterKey:binding.characterKey,
            boundAt:binding.boundAt || Date.now(),
        };
        // 这里只触发酒馆自己的debounce；若聊天已切走，上面的scope校验会直接拒绝。
        try { ctx.saveMetadataDebounced?.(); } catch {}
    }

    async function resolvePermanentArchiveForScope(scope, { create = true } = {}) {
        if (!scope) return null;
        if (!scope.hasMessages && create) return null;
        try {
            const data = await serverFetch('/archives/resolve', {
                method:'POST',
                body:JSON.stringify({ ...scope.identity, archiveId:String(scope.rememberedArchiveId || ''), create:Boolean(create) }),
            });
            if (data?.binding) rememberArchiveBindingForCurrentChat(scope, data.binding);
            return data;
        } catch (error) {
            console.warn('[0-32永久档案] 绑定解析失败，继续使用聊天metadata灾备', error);
            return null;
        }
    }

    async function savePermanentArchiveSnapshot(stateSnapshot, scope, reason='normal') {
        if (!scope?.hasMessages || !stateSnapshot || typeof stateSnapshot !== 'object') return null;
        let binding = scope.binding;
        if (!binding?.archiveId || !binding?.characterKey) binding=(await resolvePermanentArchiveForScope(scope,{create:true}))?.binding || null;
        if (!binding?.archiveId || !binding?.characterKey) return null;
        const rawText=JSON.stringify(stateSnapshot);
        const rawBytes=new TextEncoder().encode(rawText);
        const common={characterKey:binding.characterKey,archiveId:binding.archiveId,reason:String(reason||'normal').slice(0,120),identity:scope.identity};
        try {
            if(rawBytes.length<=18000){
                return await serverFetch('/archives/state',{method:'POST',body:JSON.stringify({...common,state:stateSnapshot})});
            }
            const encoded=await encodeSnapshotBytes(rawBytes);
            const chunkBytes=36*1024,total=Math.ceil(encoded.bytes.length/chunkBytes);
            const uploadId=`archive-${Date.now()}-${globalThis.crypto?.randomUUID?.()||Math.random().toString(16).slice(2)}`;
            let result=null;
            for(let index=0;index<total;index+=1){
                const chunk=encoded.bytes.subarray(index*chunkBytes,Math.min(encoded.bytes.length,(index+1)*chunkBytes));
                result=await serverFetch('/archives/state-chunk',{method:'POST',body:JSON.stringify({...common,uploadId,index,total,encoding:encoded.encoding,data:snapshotBytesToBase64(chunk)})});
            }
            if(!result?.complete)throw new Error('永久档案分片写入未完成');
            return result;
        } catch(error) {
            console.warn('[0-32永久档案] 写入失败',error);
            if(chatScopeIsCurrent(scope) && Date.now()-Number(stateRuntime.archiveSaveNoticeAt||0)>10000){stateRuntime.archiveSaveNoticeAt=Date.now();toast(`📁 永久档案写入失败：${error.message}`,'warn');}
            return null;
        }
    }

    async function savePermanentArchiveState(reason='normal', { stateSnapshot=null, scope=null }={}) {
        const capturedScope=scope || captureChatScope();
        const snapshot=stateSnapshot || (stateRuntime.state ? clone(stateRuntime.state) : null);
        return savePermanentArchiveSnapshot(snapshot,capturedScope,reason);
    }

    function schedulePermanentArchiveSync(reason='normal', delay=180, { stateSnapshot=null, scope=null }={}) {
        if (!stateSnapshot && !stateRuntime.state) return;
        const capturedScope=scope || captureChatScope();
        if(!capturedScope?.hasMessages)return;
        const snapshot=stateSnapshot || clone(stateRuntime.state);
        const key=capturedScope.chatKey;
        const previous=stateRuntime.permanentArchiveSyncs.get(key);
        if(previous?.timer)clearTimeout(previous.timer);
        const pending={scope:capturedScope,stateSnapshot:snapshot,reason:String(reason||'normal').slice(0,120),timer:null};
        pending.timer=setTimeout(async()=>{
            const current=stateRuntime.permanentArchiveSyncs.get(key);
            if(current!==pending)return;
            stateRuntime.permanentArchiveSyncs.delete(key);
            await savePermanentArchiveSnapshot(pending.stateSnapshot,pending.scope,`continuous:${pending.reason}`);
        },Math.max(40,Number(delay)||180));
        stateRuntime.permanentArchiveSyncs.set(key,pending);
    }

    async function flushPermanentArchiveSync(reason='manual-flush') {
        const scope=captureChatScope();
        if(!scope)return null;
        const pending=stateRuntime.permanentArchiveSyncs.get(scope.chatKey);
        if(pending?.timer)clearTimeout(pending.timer);
        stateRuntime.permanentArchiveSyncs.delete(scope.chatKey);
        // 导出/显式flush永远以“此刻”的不可变快照为准，而不是依赖旧debounce内容。
        return savePermanentArchiveSnapshot(stateRuntime.state?clone(stateRuntime.state):null,scope,reason);
    }

    async function exportCurrentCharacterArchiveBundle() {
        const scope=captureChatScope();
        const binding=(scope?.binding?.characterKey ? scope.binding : (await resolvePermanentArchiveForScope(scope,{create:true}))?.binding);
        if(!binding?.characterKey)throw new Error('当前角色尚未建立永久档案');
        await flushPermanentArchiveSync('before-character-cardvault-export');
        if(!chatScopeIsCurrent(scope))throw new Error('导出期间已切换聊天，请在当前聊天重新点击导出');
        const data=await serverFetch(`/archives/character/${encodeURIComponent(binding.characterKey)}/export`);
        if(data?.bundle&&typeof data.bundle==='object'){
            data.bundle.archivePolicy={mode:'per-character-per-chat',appendOnly:true,noAutomaticDeletion:true,version:2};
            data.bundle.currentChatIdentity=scope.identity;
        }
        return data;
    }

    async function importCharacterArchiveBundle(bundle) {
        const scope=captureChatScope();
        const identity=scope?.identity || currentCharacterArchiveIdentity();
        const data=await serverFetch('/archives/character/import',{method:'POST',body:JSON.stringify({bundle,characterKey:identity.characterKey,characterName:identity.characterName,currentIdentity:identity})});
        if(data?.reboundCurrentChat?.archiveId && chatScopeIsCurrent(scope)){
            stateRuntime.archiveBinding=null;
            stateRuntime.archiveBindingChatKey='';
            // CardVault恢复是用户明确授权的导入动作：立即重新读取该聊天刚接回的永久档案，不等待下一次刷新。
            await loadState({notifyMigration:false});
            if(chatScopeIsCurrent(scope))renderCurrentTab();
        }
        return data;
    }

    function emptyRows() {
        return Object.fromEntries(TABLE_ORDER.map(key => [key, []]));
    }

    function normalizeTimeCalibration(raw = {}) {
        const source = raw && typeof raw === 'object' ? raw : {};
        const value = String(source.value || '').trim().slice(0, 180);
        return {
            mode: source.mode === 'manual' && value ? 'manual' : 'auto',
            value,
            previousSceneTime: String(source.previousSceneTime || '').trim().slice(0, 180),
            appliedAtFloor: Number.isFinite(Number(source.appliedAtFloor)) ? Number(source.appliedAtFloor) : -1,
            appliedAt: String(source.appliedAt || '').trim().slice(0, 80),
        };
    }

