    function setStatePathForObject(root,path,value) {
        const keys=String(path||'').split('.').filter(Boolean);let current=root;
        for(const key of keys.slice(0,-1)){if(!current[key]||typeof current[key]!=='object')current[key]={};current=current[key];}
        if(keys.length)current[keys.at(-1)]=value;return value;
    }

    function duplicateComparableText(message) {
        return String(messageText(message) || '')
            .replace(/<!--\s*VVV_EXTRA_START[\s\S]*?VVV_EXTRA_END\s*-->/gi, '')
            .replace(/<VVV_EXTRA>[\s\S]*?<\/VVV_EXTRA>/gi, '')
            .replace(/[\u200B-\u200D\uFEFF]/g, '')
            .replace(/\s+/g, '')
            .trim();
    }

    function messageTimeMs(message) {
        const values = [message?.send_date, message?.sendDate, message?.timestamp, message?.extra?.timestamp, message?.extra?.send_date];
        for (const value of values) {
            if (value == null || value === '') continue;
            const numeric = Number(value);
            if (Number.isFinite(numeric) && numeric > 0) return numeric < 1e12 ? numeric * 1000 : numeric;
            const parsed = Date.parse(String(value));
            if (Number.isFinite(parsed)) return parsed;
        }
        return 0;
    }
    async function removeImmediateDuplicateAssistantReply() {
        if(!stateRuntime.state?.settings?.removeDuplicateAssistantReplies||stateRuntime.duplicateGuardRunning)return false;
        const scope=captureChatScope();const chat=context()?.chat||[];
        if(chat.length<3)return false;
        const duplicateIndex=chat.length-1,keepIndex=duplicateIndex-1,duplicate=chat[duplicateIndex],keep=chat[keepIndex];
        if(!duplicate||!keep||duplicate.is_user||duplicate.is_system||keep.is_user||keep.is_system)return false;
        if(!hasUserBefore(keepIndex))return false;
        const duplicateName=compactText(duplicate.name||'',100),keepName=compactText(keep.name||'',100);
        if(duplicateName&&keepName&&duplicateName!==keepName)return false;
        const a=duplicateComparableText(keep),b=duplicateComparableText(duplicate);if(a.length<30||a!==b)return false;
        const ta=messageTimeMs(keep),tb=messageTimeMs(duplicate);if(ta&&tb&&Math.abs(tb-ta)>5*60*1000)return false;
        const token={scope,at:Date.now()};stateRuntime.duplicateGuardToken=token;stateRuntime.duplicateGuardRunning=true;
        try{
            if(!chatScopeIsCurrent(scope))return false;
            keep.extra=keep.extra&&typeof keep.extra==='object'?keep.extra:{};duplicate.extra=duplicate.extra&&typeof duplicate.extra==='object'?duplicate.extra:{};
            const keepPayload=keep.extra.vvvTheaterCompanion||null,duplicatePayload=duplicate.extra.vvvTheaterCompanion||null;
            if(duplicatePayload){removeCompanionPayload(duplicatePayload);if(!keepPayload){const moved=clone(duplicatePayload);moved.floor=keepIndex;moved.signature=messageSignature(keepIndex,keep);for(const item of moved.world?.events||[])item.floor=keepIndex;keep.extra.vvvTheaterCompanion=moved;mergeCompanionPayload(moved);}}
            chat.splice(duplicateIndex,1);messageNodeForFloor(duplicateIndex)?.remove();
            await saveChatExtras(scope);
            if(!chatScopeIsCurrent(scope))return true;
            decorateCompanionOutput(keepIndex);scheduleReindex();console.warn(`[vvv小剧场] 已清理重复AI楼层：删除${duplicateIndex}，保留${keepIndex}`);return true;
        }catch(error){if(chatScopeIsCurrent(scope))console.warn('[vvv小剧场] 清理重复AI楼层失败',error);return false;}
        finally{if(stateRuntime.duplicateGuardToken===token){stateRuntime.duplicateGuardToken=null;stateRuntime.duplicateGuardRunning=false;}}
    }

    function activeCharacterObject() {
        const ctx = context() || {};
        const list = ctx.characters || globalThis.characters || [];
        const id = ctx.characterId ?? ctx.character_id ?? globalThis.this_chid;
        return ctx.character || list?.[id] || list?.find?.(item => item?.name === ctx.name2) || {};
    }

    let strongWorldInfoModulePromise = null;
    async function strongWorldInfoModule() {
        if (!strongWorldInfoModulePromise) {
            strongWorldInfoModulePromise = import('/scripts/world-info.js').catch(error => {
                strongWorldInfoModulePromise = null;
                console.warn('[0-32·强读世界书] 无法读取酒馆世界书模块，本轮跳过强读', error);
                return null;
            });
        }
        return strongWorldInfoModulePromise;
    }

    const worldBookNameKey = value => String(value ?? '').trim().toLowerCase().replace(/\.(?:png|webp|jpg|jpeg)$/i,'');
    const worldBookKeywords = entry => [...new Set([...(Array.isArray(entry?.key)?entry.key:[]), ...(Array.isArray(entry?.keysecondary)?entry.keysecondary:[])].map(value=>compactText(value,180)).filter(Boolean))];
    function strongWorldBookEntryAllowed(entry, activeCharacter) {
        if (!entry || typeof entry !== 'object') return false;
        if (entry.disable === true || entry.disabled === true || entry.enabled === false) return false;
        if ((entry.decorators || []).some?.(item => String(item).trim().toLowerCase() === '@@dont_activate')) return false;
        if (!String(entry.content ?? '').trim()) return false;
        const filter=entry.characterFilter;
        const names=Array.isArray(filter?.names)?filter.names.map(worldBookNameKey).filter(Boolean):[];
        if (names.length) {
            const candidates=[activeCharacter?.avatar,activeCharacter?.name,activeCharacter?.data?.name,context()?.name2].map(worldBookNameKey).filter(Boolean);
            const matched=names.some(name=>candidates.some(candidate=>candidate===name||candidate.includes(name)||name.includes(candidate)));
            if (filter?.isExclude ? matched : !matched) return false;
        }
        return true;
    }

    async function strongWorldBookBoundBooks() {
        const wi=await strongWorldInfoModule();
        if(!wi)return {wi:null,books:[]};
        const ctx=context()||{},character=activeCharacterObject()||{};
        const rows=[];
        const add=(name,source,boost)=>{name=String(name??'').trim();if(!name)return;const key=worldBookNameKey(name);if(!key)return;if(rows.some(row=>worldBookNameKey(row.name)===key))return;rows.push({name,source,boost});};
        add(character?.data?.extensions?.world ?? character?.extensions?.world,'角色主世界书',45);
        add(ctx?.chatMetadata?.world_info ?? ctx?.chat_metadata?.world_info,'聊天世界书',42);
        const candidates=[character?.avatar,character?.name,character?.data?.name,ctx?.name2].map(worldBookNameKey).filter(Boolean);
        for(const binding of wi.world_info?.charLore || []){
            const bindingName=worldBookNameKey(binding?.name);
            if(!bindingName||!candidates.some(candidate=>candidate===bindingName||candidate.includes(bindingName)||bindingName.includes(candidate)))continue;
            for(const name of binding?.extraBooks || [])add(name,'角色附加世界书',38);
        }
        for(const name of Array.isArray(wi.selected_world_info)?wi.selected_world_info:[])add(name,'全局世界书',28);
        return {wi,books:rows};
    }

    function strongWorldBookScanText() {
        const ctx=context()||{},chat=Array.isArray(ctx.chat)?ctx.chat:[],character=activeCharacterObject()||{};
        const recent=chat.slice(-Math.max(6,Math.min(18,Number(stateRuntime.state?.settings?.recentMessagesForAI||12))))
            .map(message=>memoryNarrativeText(message)).filter(Boolean).join('\n');
        const card=[character?.description,character?.personality,character?.scenario,character?.data?.description,character?.data?.personality,character?.data?.scenario]
            .map(value=>String(value??'').trim()).filter(Boolean).join('\n');
        return `${recent}\n${card.slice(0,7000)}`.toLowerCase();
    }

    async function buildStrongWorldBookDigest({maxChars=null}={}) {
        const settings=stateRuntime.state?.settings||{};
        if(settings.strongWorldBookRead===false)return '';
        const hardLimit=Math.max(2000,Math.min(30000,Number(maxChars??settings.strongWorldBookMaxChars??18000)||18000));
        const {wi,books}=await strongWorldBookBoundBooks();
        if(!wi||!books.length)return '';
        const scan=strongWorldBookScanText(),character=activeCharacterObject()||{},candidates=[];
        for(const book of books){
            let data=null;
            try{data=await wi.loadWorldInfo?.(book.name);}catch(error){console.warn(`[0-32·强读世界书] 读取“${book.name}”失败`,error);continue;}
            const entries=Array.isArray(data?.entries)?data.entries:Object.values(data?.entries||{});
            for(const entry of entries){
                if(!strongWorldBookEntryAllowed(entry,character))continue;
                const keys=worldBookKeywords(entry),primary=keys.filter(key=>scan.includes(String(key).toLowerCase()));
                const constant=entry.constant===true||entry.alwaysActive===true;
                const order=Number(entry.order??entry.insertion_order??0)||0;
                const score=book.boost+(constant?180:0)+(primary.length?120+Math.min(60,primary.length*12):0)+Math.max(-20,Math.min(40,order/10));
                const title=compactText(entry.comment||entry.name||keys.join('、')||`条目 ${entry.uid??''}`,180)||'未命名条目';
                const content=String(entry.content||'').replace(/\u0000/g,'').replace(/\r\n?/g,'\n').trim().slice(0,5000);
                if(content)candidates.push({book,title,content,score,constant,matched:primary.slice(0,8),uid:entry.uid});
            }
        }
        if(!candidates.length)return '';
        candidates.sort((a,b)=>b.score-a.score||Number(b.constant)-Number(a.constant)||String(a.book.name).localeCompare(String(b.book.name),'zh-CN'));
        const lines=['【0-32 强读世界书｜高优先级硬设定】','以下内容来自当前角色/当前聊天/当前全局实际绑定的世界书。请主动读取并遵守；世界书中的静态设定优先于旧记忆或模型惯性，但最新user明确行动与本轮已发生剧情仍是当前现实。不要复述世界书，直接按设定继续剧情。'];
        let used=lines.join('\n').length,accepted=0;
        for(const item of candidates){
            if(accepted>=80)break;
            const heading=`\n【${item.book.source}｜${item.book.name}｜${item.title}${item.matched.length?`｜命中:${item.matched.join('、')}`:''}】\n`;
            const room=hardLimit-used-heading.length;
            if(room<160)break;
            const body=item.content.slice(0,Math.min(5000,room));
            if(!body)continue;
            lines.push(`${heading}${body}`);used+=heading.length+body.length;accepted+=1;
        }
        if(!accepted)return '';
        return lines.join('\n').slice(0,hardLimit);
    }

