                for(const token of queryTokens){
                    if(token.length<2)continue;
                    if(token===alias)score=Math.max(score,95+alias.length);
                    else if(alias.length>=2&&token.includes(alias))score=Math.max(score,65+alias.length);
                    else if(alias.length>=2&&alias.includes(token))score=Math.max(score,45+token.length);
                }
