        const totalItems=filtered?filtered.length:count; const totalPages=Math.max(1,Math.ceil(totalItems/S9_PAGE_SIZE)); let page=s9CatalogPageState(platform); if(page>totalPages){page=totalPages;s9SetCatalogPage(platform,page,totalPages)}
        const start=(page-1)*S9_PAGE_SIZE; const indices=filtered?filtered.slice(start,start+S9_PAGE_SIZE):Array.from({length:Math.min(S9_PAGE_SIZE,count-start)},(_,j)=>start+j);
        return {items:indices.map(i=>s9CatalogItem(platform,i)).filter(Boolean),page,totalPages,totalItems};
