    const S8_ORDER_KIND_LABELS = Object.freeze({shopping:'购物订单',food:'外卖订单',ride:'打车订单',travel:'航旅订单',campus:'校园缴费'});
    function s8OrderPlatformForKind(kind='') { return ({taobao:'taobao',jd:'jd',eleme:'eleme',meituan:'meituan',ride:'ride',travel:'travel',campus:'campus'})[kind] || String(kind||'other'); }
    function s8OrderPlatformLabel(platform='') { return S8_ORDER_PLATFORM_LABELS[platform] || compactText(platform,40) || '订单'; }
    function s8OrderStatusLabel(order={}) {
        const platform=String(order.platform||''); const status=String(order.status||'paid');
        return S8_ORDER_STATUS_LABELS[platform]?.[status] || status || '处理中';
    }
    function s8OrderItems(order={}) {
        const rows=Array.isArray(order.items)?order.items:[];
        if(rows.length)return rows.map((row,index)=>({
            id:row.productId||row.itemId||row.id||`item-${index}`,
            name:compactText(row.name||row.title||'商品',160)||'商品',
            price:Math.max(0,s8Money(row.price)),qty:Math.max(1,Number(row.qty||1)),icon:row.icon||'📦',
            storeId:compactText(row.storeId,120),storeName:compactText(row.storeName||row.store,160),sku:compactText(row.sku||row.skuCode,120),
        }));
        return order.title ? [{id:'summary',name:compactText(order.title,160),price:Math.max(0,s8Money(order.amount)),qty:1,icon:order.platform==='travel'?'🎫':order.platform==='ride'?'🚕':'🧾'}] : [];
    }
    function s8OrderTimeline(order,status=order?.status||'paid',label=s8OrderStatusLabel({...order,status}),detail='') {
        if(!order)return;
        order.timeline=Array.isArray(order.timeline)?order.timeline:[];
        if(order.timeline.some(row=>row.status===status&&compactText(row.label,80)===compactText(label,80)&&compactText(row.detail,240)===compactText(detail,240)))return;
        const row={status,label:compactText(label,80),detail:compactText(detail,240),time:phoneClock().time,storyTime:compactText(stateRuntime.state?.scene?.time||'',120),createdAt:Date.now()};
        order.timeline.push(row);
        const phone=ensurePhoneEcosystem();
        phone.orderEvents=Array.isArray(phone.orderEvents)?phone.orderEvents:[];
        phone.orderEvents.push({id:uid('order-event'),orderId:order.id,platform:order.platform,status:row.status,label:row.label,detail:row.detail,time:row.time,storyTime:row.storyTime,createdAt:row.createdAt,sourceFloor:Math.max(0,(context()?.chat?.length||1)-1)});
        phone.orderRevision=Math.max(0,Number(phone.orderRevision||0))+1;
        const terminal=['delivered','已完成','已使用','refunded','cancelled','已取消'].includes(status);
        s12ScheduleCalendar({id:`order-calendar-${order.id}`,title:`${terminal?'已完成 · ':''}${s8OrderPlatformLabel(order.platform)} · ${order.storeName||order.merchant||s8OrderItemSummary(order,80)}`,date:order.storyTime||order.time,note:`${label}${detail?` · ${detail}`:''}`,source:'order',relatedId:order.id,route:'orders',dueFloor:terminal?-1:Number(order.sourceFloor||0)+(order.kind==='food'?3:6)});
    }
    function s8NormalizeOrder(order,platform='') {
        if(!order||typeof order!=='object')return null;
        order.platform=order.platform||platform||'other';
        order.id=compactText(order.id,120)||uid(`${order.platform}-order`);
        order.kind=order.kind||({taobao:'shopping',jd:'shopping',eleme:'food',meituan:'food',ride:'ride',travel:'travel',campus:'campus'}[order.platform]||'other');
        order.items=Array.isArray(order.items)?order.items:[];
        order.amount=Math.round(s8Money(order.amount||order.payable||0)*100)/100;
        order.createdAt=Number(order.createdAt||Date.now());
        order.time=compactText(order.time,80)||phoneClock().time;
        order.storyTime=compactText(order.storyTime||order.createdStoryTime||'',120)||compactText(stateRuntime.state?.scene?.time||'',120);
        order.progressTick=Math.max(0,Number(order.progressTick||0));
        order.awareness=order.awareness&&typeof order.awareness==='object'?order.awareness:{};
        order.awareness.scope='co-located-observable';
        order.awareness.sceneLocation=compactText(order.awareness.sceneLocation||order.sceneLocation||'',180)||compactText(stateRuntime.state?.scene?.location||'',180);
        order.awareness.sourceFloor=Number.isFinite(Number(order.awareness.sourceFloor))?Number(order.awareness.sourceFloor):Number(order.sourceFloor??-1);
        order.awareness.directlyInformed=Array.isArray(order.awareness.directlyInformed)?[...new Set(order.awareness.directlyInformed.map(name=>relationPartyName(name)).filter(Boolean))].slice(0,80):[];
        order.issues=Array.isArray(order.issues)?order.issues:[];
        order.afterSales=order.afterSales&&typeof order.afterSales==='object'?order.afterSales:{};
        order.timeline=Array.isArray(order.timeline)?order.timeline:[];
        if(!order.timeline.length)order.timeline=[{status:order.status||'paid',label:s8OrderStatusLabel({...order,status:order.status||'paid'}),detail:'订单已创建',time:order.time,storyTime:order.storyTime,createdAt:order.createdAt}];
        return order;
    }
    function s8AllPhoneOrders() {
        const phone=ensurePhoneEcosystem(); if(!phone)return [];
        const ext=s9EnsureExtendedApps(); const rows=[];
        for(const platform of ['taobao','jd','eleme','meituan'])for(const order of phone.commerce?.[platform]?.orders||[]){s8NormalizeOrder(order,platform);rows.push(order);}
        for(const order of ext?.ride?.orders||[]){s8NormalizeOrder(order,'ride');rows.push(order);}
        for(const order of ext?.travel?.orders||[]){s8NormalizeOrder(order,'travel');rows.push(order);}
        return rows.sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
    }
    function s8OrderMatchesFilter(order,filter='all') {
        if(filter==='all')return true;
        if(filter==='shopping')return ['taobao','jd'].includes(order.platform);
        if(filter==='food')return ['eleme','meituan'].includes(order.platform);
        if(filter==='shipping')return ['taobao','jd'].includes(order.platform)&&!['delivered','cancelled'].includes(order.status);
        return order.platform===filter;
    }
    function s12OrderActionMarkup(order){
        const terminal=['refunded','cancelled','已取消'].includes(order.status),delivered=['delivered','已完成','已使用'].includes(order.status);
        if(terminal)return `<span>${esc(s8OrderStatusLabel(order))}</span>`;
        if(order.status==='refund-pending')return '<button disabled>退款处理中</button>';
        if(order.status==='exception')return `<button data-phone-order-action="resume" data-phone-order-id="${esc(order.id)}">继续处理</button><button class="danger-soft" data-phone-order-action="refund" data-phone-order-id="${esc(order.id)}">申请退款</button>`;
        if(delivered)return `<button data-phone-order-action="receiver" data-phone-order-id="${esc(order.id)}">代收人</button><button data-phone-order-action="aftersale" data-phone-order-id="${esc(order.id)}">申请售后</button>`;
        const rider=order.kind==='food'&&order.status==='delivering'?`<button data-phone-order-action="rider" data-phone-order-id="${esc(order.id)}">联系骑手</button>`:'';
        return `${rider}<button data-phone-order-action="issue" data-phone-order-id="${esc(order.id)}">遇到问题</button><button class="danger-soft" data-phone-order-action="cancel" data-phone-order-id="${esc(order.id)}">取消订单</button>`;
    }
    function phoneOrderDetailMarkup(order) {
        const items=s8OrderItems(order); const timeline=(order.timeline||[]).slice().reverse();
        const merchant=order.storeName||order.merchant||({ride:order.destination,travel:order.code}[order.platform]||s8OrderPlatformLabel(order.platform));
        return `<div class="vvvtm-phone-app-page vvvtm-order-page"><header class="vvvtm-phone-app-head"><button data-phone-order-back>‹</button><div><b>${esc(s8OrderPlatformLabel(order.platform))} · 订单详情</b><small>${esc(order.id)}</small></div><button data-phone-home>⌂</button></header><main class="vvvtm-order-detail"><section class="vvvtm-order-status-card"><small>${esc(merchant||'订单')}</small><strong>${esc(s8OrderStatusLabel(order))}</strong><p>${esc(phoneOrderStoryStamp(order))}${order.receiver?` · ${esc(order.receiver)}代收`:''}</p></section><section class="vvvtm-order-items"><h3>商品明细</h3>${items.length?items.map(item=>`<article><span>${item.icon}</span><div><b>${esc(item.name)}</b><small>${s8MoneyText(item.price)} × ${item.qty}</small></div><em>${s8MoneyText(item.price*item.qty)}</em></article>`).join(''):'<p>此订单没有商品明细。</p>'}</section><section class="vvvtm-order-total"><span>${order.externalPayer?'他人代付':'实付金额'}</span><strong>${s8MoneyText(order.amount)}</strong></section>${order.issues?.length?`<section class="vvvtm-order-issues"><h3>异常与售后</h3>${order.issues.slice().reverse().map(issue=>`<article><b>${esc(issue.label||issue.type)}</b><p>${esc(issue.note||'')}</p><small>${esc(issue.time||'')}</small></article>`).join('')}</section>`:''}<section class="vvvtm-order-timeline"><h3>订单进度</h3>${timeline.length?timeline.map(item=>`<article class="${item===timeline[0]?'current':''}"><i></i><div><b>${esc(item.label||item.status)}</b><small>${esc(parseStoryDateTime(item.storyTime||'').label||phoneOrderStoryStamp(order)||item.time||'')}</small>${item.detail?`<p>${esc(item.detail)}</p>`:''}</div></article>`).join(''):'<p>暂无进度记录。</p>'}</section><section class="vvvtm-order-service-actions">${s12OrderActionMarkup(order)}</section><footer class="vvvtm-order-actions"><button data-phone-order-back>继续浏览</button><button data-phone-order-center>全部订单</button></footer></main></div>`;
    }
    function s12SetOrderIssue(order,type='other',note='',options={}){
        if(!order)return false;s8NormalizeOrder(order,order.platform);const floor=Math.max(0,(context()?.chat?.length||1)-1);const labels={late:'配送延迟',missing:'商品缺失',wrong:'商品错送',damaged:'商品损坏',address:'地址问题',stock:'商家缺货',cancel:'用户取消',other:'订单异常'};
        const issue={id:uid('order-issue'),type,label:labels[type]||labels.other,note:compactText(note,400),time:phoneClock().time,floor,createdAt:Date.now()};order.issues.push(issue);
        order.afterSales.previousStatus=order.status;order.status=options.status||'exception';order.afterSales.activeIssueId=issue.id;
        s8OrderTimeline(order,order.status,s8OrderStatusLabel(order),`${issue.label}${issue.note?` · ${issue.note}`:''}`);s8AddNotification(s8OrderPlatformLabel(order.platform),issue.label,`${order.storeName||order.merchant||'订单'} · ${issue.note||s8OrderItemSummary(order,120)}`,{type:'order-issue',route:'orders',relatedId:order.id,dedupeKey:`issue-${issue.id}`});
        s8RecordPhoneActivity('order-issue',`${s8OrderPlatformLabel(order.platform)} · ${issue.label}`,issue.note||s8OrderItemSummary(order,200),{relatedId:order.id,route:'orders'});return true;
    }
    function s12RequestOrderRefund(order,reason='用户申请退款'){
        if(!order||['refunded','cancelled'].includes(order.status))return false;const floor=Math.max(0,(context()?.chat?.length||1)-1);order.afterSales ||= {};order.afterSales.previousStatus=order.status;order.afterSales.reason=compactText(reason,400);order.afterSales.requestedFloor=floor;order.afterSales.refundDueFloor=floor+1;order.status='refund-pending';
        s8OrderTimeline(order,'refund-pending','退款处理中',order.afterSales.reason);s8AddNotification(s8OrderPlatformLabel(order.platform),'退款申请已提交',`${order.storeName||order.merchant||'订单'} · ${s8MoneyText(order.amount)}`,{route:'orders',relatedId:order.id,dedupeKey:`refund-request-${order.id}`});return true;
    }
    function s12CompleteOrderRefund(order){
        if(!order||order.afterSales?.refundTransactionId)return false;const account=order.payAccount==='wechat'?'wechat':'alipay';const row=s8RecordTransaction({account,amount:Math.abs(s8Money(order.amount)),title:`${s8OrderPlatformLabel(order.platform)}订单退款 · ${s8OrderItemSummary(order,100)}`,counterparty:order.storeName||order.merchant||s8OrderPlatformLabel(order.platform),category:'refund',source:'order-refund',floor:Math.max(0,(context()?.chat?.length||1)-1)});order.afterSales ||= {};order.afterSales.refundTransactionId=row.id;order.status='refunded';order.refundedAt=Date.now();
        s8OrderTimeline(order,'refunded','退款成功',`${s8MoneyText(order.amount)} 已原路退回${s8PaymentAccountLabel(account)}`);s8AddNotification(s8OrderPlatformLabel(order.platform),'退款成功',`${s8MoneyText(order.amount)} 已退回${s8PaymentAccountLabel(account)}`,{route:'orders',relatedId:order.id,dedupeKey:`refund-done-${order.id}`});return true;
    }
    function s12ApplyOrderAction(orderId='',action='',data={}){
        const order=s8AllPhoneOrders().find(item=>item.id===compactText(orderId,120));if(!order)return false;
        if(action==='cancel'){s12SetOrderIssue(order,'cancel',data.note||'订单已取消',{status:'cancelled'});return s12CompleteOrderRefund(order);}
        if(action==='refund'||action==='aftersale')return s12RequestOrderRefund(order,data.note||'用户申请售后退款');
        if(action==='issue')return s12SetOrderIssue(order,data.type||'other',data.note||'用户报告订单异常');
        if(action==='resume'){order.status=order.afterSales?.previousStatus||'paid';order.afterSales.activeIssueId='';s8OrderTimeline(order,order.status,'恢复处理','异常已处理，订单继续原流程');return true;}
        if(action==='receiver'){const npc=relationPartyName(data.receiver);if(!npc)return false;order.receiver=npc;order.status='delivered';order.deliveredFloor=Math.max(0,(context()?.chat?.length||1)-1);s8OrderTimeline(order,'delivered','已由他人代收',`${npc} 已代收：${s8OrderItemSummary(order,200)}`);s12RecordKnowledge({relatedId:order.id,subject:'代收订单',summary:s8OrderItemSummary(order,240),npc,method:'received',source:'order',floor:order.deliveredFloor});return true;}
        return false;
    }
    function phoneOrdersMarkup() {
        const filter=stateRuntime.phoneOrderFilter||'all'; const rows=s8AllPhoneOrders().filter(order=>s8OrderMatchesFilter(order,filter));
        const selected=stateRuntime.phoneSelectedOrderId?s8AllPhoneOrders().find(order=>order.id===stateRuntime.phoneSelectedOrderId):null;
        if(selected)return phoneOrderDetailMarkup(selected);
        const tabs=[['all','全部'],['shopping','购物'],['food','外卖'],['shipping','待收货'],['ride','打车'],['travel','航旅']];
        return `<div class="vvvtm-phone-app-page vvvtm-orders-page"><header class="vvvtm-phone-app-head"><button data-phone-home>‹</button><div><b>订单</b><small>${rows.length} 笔剧情订单 · 可查看完整进度</small></div><button data-phone-order-refresh>↻</button></header><main><nav class="vvvtm-order-tabs">${tabs.map(([id,label])=>`<button class="${filter===id?'active':''}" data-phone-order-filter="${id}">${label}</button>`).join('')}</nav>${rows.length?`<section class="vvvtm-order-list">${rows.map(order=>{const items=s8OrderItems(order);const merchant=order.storeName||order.merchant||({ride:order.destination,travel:order.code}[order.platform]||s8OrderPlatformLabel(order.platform));return `<button class="vvvtm-order-card" data-phone-order-open="${esc(order.id)}"><span class="vvvtm-order-icon">${order.platform==='travel'?'🎫':order.platform==='ride'?'🚕':order.platform==='eleme'||order.platform==='meituan'?'🛵':'📦'}</span><div><header><b>${esc(s8OrderPlatformLabel(order.platform))}</b><small>${esc(phoneOrderStoryStamp(order))}</small></header><strong>${esc(merchant||'订单')}</strong><p>${esc(items.map(item=>`${item.name} ×${item.qty}`).join('、')||'订单明细')}</p><footer><span>${esc(s8OrderStatusLabel(order))}</span><em>${s8MoneyText(order.amount)}</em></footer></div></button>`;}).join('')}</section>`:'<div class="vvvtm-phone-empty-chat"><span>🧾</span><b>还没有订单</b><small>在淘宝、京东、外卖、打车或航旅完成一次模拟支付后，订单会出现在这里。</small></div>'}</main></div>`;
    }
    function s8NormalizePaymentAction(action={}) {
        const payment=clone(action||{}); payment.kind=compactText(payment.kind,40); payment.account=payment.account==='wechat'?'wechat':'alipay';
        payment.items=s8OrderItems({items:payment.items||[],title:payment.title,amount:payment.amount});
        payment.subtotal=Math.round(payment.items.reduce((sum,row)=>sum+s8Money(row.price)*row.qty,0)*100)/100;
        payment.discount=Math.max(0,s8Money(payment.discount));
        payment.deliveryFee=Math.max(0,Math.round((s8Money(payment.amount)-payment.subtotal+payment.discount)*100)/100);
        payment.amount=Math.round(Math.max(0,s8Money(payment.amount||payment.subtotal-payment.discount))*100)/100;
        payment.platform=s8OrderPlatformForKind(payment.kind);
        return payment;
    }
    function s8TaobaoProduct(id) {
        return s9ProductById(id) || ensurePhoneEcosystem()?.commerce?.taobao?.products?.find(row=>row.id===id) || null;
    }
    function s9JdProduct(id) { return s9ProductById(id) || null; }
    function s8ElemeStore(id) { return s9FoodStoreById(id) || ensurePhoneEcosystem()?.commerce?.eleme?.stores?.find(row=>row.id===id) || null; }
    function s9MeituanStore(id) { return s9FoodStoreById(id) || null; }
    function s8CartTotal(kind='taobao') {
        const phone=ensurePhoneEcosystem(); if(!phone)return 0;
        if(kind==='taobao'||kind==='jd') return (phone.commerce[kind].cart||[]).reduce((sum,row)=>{const p=kind==='jd'?s9JdProduct(row.productId):s8TaobaoProduct(row.productId);return sum+(p?s8Money(p.price)*Math.max(1,Number(row.qty||1)):0)},0);
        if(kind==='eleme'||kind==='meituan') return (phone.commerce[kind].cart||[]).reduce((sum,row)=>{const store=kind==='meituan'?s9MeituanStore(row.storeId):s8ElemeStore(row.storeId);const item=store?.menu?.find(x=>x.id===row.itemId);return sum+(item?s8Money(item.price)*Math.max(1,Number(row.qty||1)):0)},0);
        return 0;
    }
    function s8PaymentAccountLabel(account) { return account==='wechat'?'微信支付':'支付宝'; }
