        // 不监听小剧场自身的普通 DOM 更新，避免 MutationObserver 自触发死循环。
        const observer=new MutationObserver(mutations=>{
            const needsRepair=mutations.some(mutation=>{
                const removed=[...mutation.removedNodes].some(node=>
                    node?.nodeType===1 && (
                        ['vvvtm-topnav-button','vvvtm-modal','vvvtm-wand-entry','vvvtm-settings-entry'].includes(node.id) ||
                        node.querySelector?.('#vvvtm-topnav-button,#vvvtm-modal,#vvvtm-wand-entry,#vvvtm-settings-entry')
                    )
                );
                const menuAdded=[...mutation.addedNodes].some(node=>
                    node?.nodeType===1 && (
                        node.id==='extensionsMenu' || node.id==='chat' ||
                        node.querySelector?.('#extensionsMenu,#chat')
                    )
                );
                return removed||menuAdded;
            });
            if(needsRepair)scheduleRepairUI();
        });
        observer.observe(document.body||document.documentElement,{childList:true,subtree:true});
        bindCompanionDomObserver();
        globalThis.addEventListener('resize',scheduleFabPlacement,{passive:true});
        globalThis.addEventListener('orientationchange',()=>setTimeout(scheduleFabPlacement,180),{passive:true});
        globalThis.visualViewport?.addEventListener('resize',scheduleFabPlacement,{passive:true});
        globalThis.visualViewport?.addEventListener('scroll',scheduleFabPlacement,{passive:true});
        globalThis.VVVUnifiedCore?.overlays?.register?.('theater',{close:()=>{closeModal();const phone=document.getElementById('vvvtm-role-phone');if(phone)phone.hidden=true;}});
        globalThis.openVVVTheaterMemory=openModal;
        console.info(`[0-32 · 永不落幕的剧场·记忆中枢] v${VERSION} 已加载（P41-S4·唯一完整手机）`);
