        return `<button class="vvvtm-worldmap-pin ${current?'current':''} ${active?'active':''}" style="left:${Number(row.x)||0}px;top:${Number(row.y)||0}px" data-worldmap-place="${esc(row.id)}" title="${esc(row.name)}"><i>${current?'你':s15MapIcon(row.type)}</i><span>${esc(row.name)}</span></button>`;
