            overlay=document.createElement('div');overlay.id='vvvtm-worldmap-overlay';overlay.dataset.vvvtmReturnPhone=phoneVisible?'1':'0';overlay.dataset.vvvtmReturnTheater=theaterVisible?'1':'0';document.body.append(overlay);
            // iPhone WebKit otherwise composites the full phone, theater blur and
