            if(garment){const description=compactText(dialog.querySelector('[data-avatar-editor-description]')?.value,800)||name;systems.studio.garments.push({id:uid('garment'),name,description,category:/鞋|靴/.test(name)?'shoes':/帽|耳环|项链|围巾|包|眼镜/.test(name)?'accessory':'clothing',owner:active?.name||'',source:'手工登记',wornBy:[],createdAt:Date.now()});await saveState({immediate:true,refresh:false,reason:'manual-garment'});}
            else {let subject=systems.studio.subjects.find(row=>npcNameKey(row.name)===npcNameKey(name));if(!subject){subject={id:s15StableId('subject',`npc|${name}`),name,role:'npc',basePrompt:'',negativePrompt:'',composition:'full-body',styleProfile:'anime-accent',referenceAssetId:'',currentImageId:'',mirror:{},lastAutoFloor:-1};systems.studio.subjects.push(subject);}stateRuntime.avatarSubjectId=subject.id;await saveState({immediate:true,refresh:false,reason:'add-avatar-subject'});}
